<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('network','create');global $conn;$tenantId=(int)getCurrentTenantId();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$name=trim($_POST['name']??'');$location=trim($_POST['location']??'');$status=$_POST['status']??'active';$description=trim($_POST['description']??'');if($name==='')$error='Site name is required.';else{$q=$conn->prepare("INSERT INTO network_sites(tenant_id,name,location,status,description) VALUES(?,?,?,?,?)");$q->bind_param('issss',$tenantId,$name,$location,$status,$description);if($q->execute())redirect('index.php');$error=$q->error?:'Unable to save site.';$q->close();}}
$pageTitle='Add Network Site';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Add Network Site</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="form-group"><label>Name</label><input name="name" required></div><div class="form-group"><label>Location</label><input name="location"></div><div class="form-group"><label>Status</label><select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div class="form-group"><label>Description</label><textarea name="description"></textarea></div><button type="submit">Save Site</button> <a href="index.php">Cancel</a></form></div><?php require_once '../includes/footer.php';?>